int topo(int V, int adj[][MAXD], int deg_out[], int indeg[], int order[]) {
  int q[V], head = 0, tail = 0, cnt = 0;
  for (int v = 0; v < V; v++) if (indeg[v] == 0) q[tail++] = v;
  while (head < tail) {
    int u = q[head++]; order[cnt++] = u;
    for (int i = 0; i < deg_out[u]; i++)
      if (--indeg[adj[u][i]] == 0) q[tail++] = adj[u][i];
  }
  return cnt == V;   // 0 => cycle
}
